<script setup>
import { computed } from 'vue';
import { recoveryGroups,recoveryTotals } from '../../lib/recovery-domain';
const props=defineProps({rows:{type:Array,required:true},kind:{type:String,required:true}});
const groups=computed(()=>recoveryGroups(props.rows,props.kind==='employees')),total=computed(()=>recoveryTotals(props.rows));
const money=value=>Number(value||0).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});
const reconciliation=computed(()=>[['Gross pending due as per ERP',total.value.gross],['Less: collected during this drive',-total.value.collected],['Less: not collectable - proposed removal',-total.value.writeoff],['Real balance to be carried forward',total.value.real],['  of which - committed with a date',total.value.committed],['  of which - disputed / on hold',total.value.dispute],['  of which - not yet updated by branch',total.value.pending]]);
</script>
<template><table v-if="kind==='reconciliation'" id="cleanTbl" style="max-width:640px"><thead><tr><th>Particulars</th><th class="num">Amount</th></tr></thead><tbody><tr v-for="([label,value],index) in reconciliation" :key="label" :class="{tot:index===3}"><td>{{label}}</td><td class="num">{{money(value)}}</td></tr></tbody></table><table v-else :id="kind==='employees'?'empTbl':'brTbl'"><thead><tr><th>{{kind==='employees'?'Booked by':'Branch'}}</th><th>Invoices</th><th>Gross due</th><th>Collected</th><th>Committed</th><th>To remove</th><th>Real balance</th><th>Updated</th></tr></thead><tbody><tr v-for="group in groups" :key="group.key"><td><span :class="{code:kind==='branches'}">{{group.label}}</span><span v-if="group.branch" class="sub">{{group.branch}}</span></td><td class="num">{{group.n}}</td><td v-for="field in ['gross','collected','committed','writeoff','real']" :key="field" class="num">{{money(group[field])}}</td><td class="ctr">{{Math.round(group.done/group.n*100)}}%</td></tr><tr v-if="!groups.length"><td colspan="8">Nothing to show.</td></tr></tbody><tfoot><tr><td>TOTAL</td><td class="num">{{total.n}}</td><td v-for="field in ['gross','collected','committed','writeoff','real']" :key="field" class="num">{{money(total[field])}}</td><td></td></tr></tfoot></table></template>
